<template>
  <div class="popup-overlay" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="popup-content">
      <div class="header">
        <div class="semi-header">
          <svg
            width="22"
            height="22"
            viewBox="0 0 22 22"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M8.5 6C8.5 5.44772 8.94771 5 9.5 5L16.5 5C17.0523 5 17.5 5.44772 17.5 6C17.5 6.55229 17.0523 7 16.5 7L9.5 7C8.94771 7 8.5 6.55229 8.5 6Z"
              fill="#FBB040"
            />
            <path
              d="M9.5 9C8.94771 9 8.5 9.44772 8.5 10C8.5 10.5523 8.94771 11 9.5 11H13C13.5523 11 14 10.5523 14 10C14 9.44772 13.5523 9 13 9H9.5Z"
              fill="#FBB040"
            />
            <path
              fill-rule="evenodd"
              clip-rule="evenodd"
              d="M18.2563 0.366058C17.3926 0.249942 16.3014 0.249969 14.9781 0.250001L10.931 0.250001C9.60769 0.249969 8.5164 0.249942 7.65275 0.366058C6.746 0.487966 5.9452 0.753753 5.304 1.39495C4.66281 2.03615 4.39702 2.83695 4.27511 3.74369C4.15899 4.60736 4.15902 5.6986 4.15906 7.02195L4.15906 14.3091C4.15906 14.5919 4.15906 14.7334 4.07119 14.8212C3.98332 14.9091 3.8419 14.9091 3.55905 14.9091L3.08344 14.9091C2.65936 14.9089 2.22951 14.9088 1.87244 14.9682C1.44525 15.0393 0.998763 15.2128 0.654575 15.6424C0.333301 16.0435 0.236304 16.4787 0.251513 16.9104C0.263525 17.2512 0.350162 17.6332 0.429535 17.9831C0.626294 18.8528 0.98532 19.8094 1.56295 20.5101C2.16342 21.2384 3.01879 21.75 4.12398 21.75L17.8347 21.75C19.2282 21.75 20.278 21.161 20.9321 20.1638C21.5448 19.23 21.75 18.033 21.75 16.8636L21.75 7.02197C21.75 5.69861 21.75 4.60737 21.6339 3.74369C21.512 2.83695 21.2462 2.03615 20.605 1.39495C19.9638 0.753753 19.163 0.487966 18.2563 0.366058ZM6.71377 14.9091C6.43093 14.9091 6.28951 14.9091 6.20164 14.8213C6.11377 14.7334 6.11377 14.592 6.11377 14.3091L6.11377 7.09095C6.11377 5.68126 6.11585 4.72229 6.21239 4.00417C6.30516 3.31417 6.46873 2.99458 6.68624 2.77707C6.90376 2.55955 7.22334 2.39599 7.91335 2.30322C8.63147 2.20667 9.59043 2.20459 11.0001 2.20459L14.9092 2.20459C16.3189 2.20459 17.2779 2.20667 17.996 2.30322C18.686 2.39599 19.0056 2.55955 19.2231 2.77707C19.4406 2.99458 19.6042 3.31417 19.697 4.00417C19.7935 4.72229 19.7956 5.68126 19.7956 7.09096L19.7956 16.8637C19.7956 17.8532 19.6135 18.6108 19.298 19.0918C19.024 19.5095 18.6048 19.7955 17.8349 19.7955C17.4034 19.7955 17.0724 19.6191 16.7819 19.2668C16.4685 18.8867 16.2187 18.3115 16.06 17.6103C15.9543 17.143 15.8508 16.6854 15.7463 16.3635C15.6437 16.0476 15.4758 15.6313 15.1061 15.3364C14.7596 15.0599 14.3672 14.9763 14.044 14.9415C13.7424 14.909 13.3743 14.9091 12.9832 14.9091L6.71377 14.9091Z"
              fill="#FBB040"
            />
          </svg>
          <h3 v-if="type === 'view'">{{ $t("ViewRole") }}</h3>
          <h3 v-if="type === 'add'">{{ $t("AddRole") }}</h3>
          <h3 v-if="type === 'edit'">{{ $t("EditRole") }}</h3>
          <h3 v-if="type === 'delete'">{{ $t("DeleteRole") }}</h3>
        </div>
        <button class="close-button" @click="$emit('close')">X</button>
      </div>
      <div class="form" v-if="type !== 'delete'">
        <!-- Loading state for edit mode -->
        <div v-if="loading && type === 'edit'" class="loading-container">
          <p>{{ $t("LoadingPermissions") || "Loading permissions..." }}</p>
        </div>
        <div v-else>
          <!-- Add Mode: Select Admin User -->
          <div v-if="type === 'add'">
            <div class="input-container" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
              <label class="floating-label" :class="{'rtl-label': $i18n.locale === 'ar'}">{{ $t('SelectAdminUser') }}</label>
              <select v-model="formData.selectedUserId">
                <option value="">{{ $t('selectUser') }}</option>
                <option v-for="user in adminUsers" :key="user.user.id" :value="user.user.id">
                  {{ user.user.name }} ({{ user.user.email }})
                </option>
              </select>
            </div>
          </div>
          <!-- Role selection (shared for add/edit) -->
          <div class="input-container" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
            <label class="floating-label" :class="{'rtl-label': $i18n.locale === 'ar'}">{{ $t('role') }}</label>
            <div v-if="type === 'view'" class="role-display">
              <span v-for="role in formData.role" :key="role.id || role" class="role-tag">
                {{ typeof role === 'object' ? role.name : role }}
              </span>
            </div>
            <div v-else class="role-selector">
              <select @change="addRole" class="role-dropdown" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
                <option value="">{{ $t("selectRole") }}</option>
                <option 
                  v-for="role in availableRoles" 
                  :key="role" 
                  :value="role"
                  :disabled="formData.role.some(userRole => {
                    const roleName = typeof userRole === 'object' ? userRole.name : userRole;
                    return roleName === role;
                  })"
                >
                  {{ role }}
                </option>
              </select>
              <div class="selected-roles">
                <span v-for="role in formData.role" :key="role.id || role" class="role-tag">
                  {{ typeof role === 'object' ? role.name : role }}
                  <button 
                    type="button" 
                    @click="removeRole(role)" 
                    class="remove-role"
                    :disabled="removingRole"
                  >
                    {{ removingRole ? '...' : '&times;' }}
                  </button>
                </span>
              </div>
            </div>
          </div>
          <!-- Permissions Section (as before) -->
          <div class="input-container" v-if="formData.role.length > 0">
            <label>{{ $t("Permissions") }}</label>
            <div v-if="type === 'view'" class="permissions-display">
              <div v-for="role in formData.role" :key="role.id || role" class="role-permissions">
                <h4>{{ typeof role === 'object' ? role.name : role }}</h4>
                <div class="permission-tags">
                  <span v-for="permission in getSelectedPermissionsForRole(role)" :key="permission" class="permission-tag">
                    {{ $t(permission) }}
                  </span>
                </div>
              </div>
            </div>
            <div v-else class="permissions-selector">
              <div v-if="loadingPermissions" class="loading-permissions">
                <p>{{ $t("LoadingPermissions") || "Loading permissions..." }}</p>
              </div>
              <div v-else class="roles-container">
                <div v-for="role in formData.role" :key="role.id || role" class="role-permission-group">
                  <h4>{{ typeof role === 'object' ? role.name : role }}</h4>
                  <div class="permission-checkboxes">
                    <div 
                      v-for="permission in rolePermissions[typeof role === 'object' ? role.name : role]" 
                      :key="permission.id || permission" 
                      class="permission-checkbox"
                    >
                      <input 
                        type="checkbox" 
                        :id="`${typeof role === 'object' ? role.name : role}-${permission.id || permission}`"
                        :value="permission.id || permission"
                        v-model="formData.permissions[typeof role === 'object' ? role.name : role]"
                      />
                      <label :for="`${typeof role === 'object' ? role.name : role}-${permission.id}`">{{ $t(permission.name) || permission.name }}</label>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <p style="text-align: center; color: black" v-if="type === 'delete'">
        {{ $t("confirmDeleteRole") }}
      </p>
      <p style="text-align: center" v-if="type === 'delete'">
        {{ $t("deleteWarning") }}
      </p>

      <div class="popup-actions">
        <button
          style="background-color: #f02116"
          v-if="type === 'delete'"
          @click="deleteRole"
        >
          {{ $t("delete") }}
        </button>
        <button v-if="type === 'add' || type === 'edit'" @click="saveRole" :disabled="assigningPermissions">
          {{ assigningPermissions ? $t("Saving") : $t("Save") }}
        </button>
        <button @click="$emit('close')">{{ $t("Cancel") }}</button>
      </div>
    </div>
  </div>
</template>

<script>
import { useToast } from "vue-toastification";
import axiosInstance from "@/axios.js";

export default {
  props: {
    type: String,
    data: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    return {
      formData: {
        ...this.data,
        // Removed name, email, phone, password, verify_phone, verify_email
        role: this.data.roles || this.data.role || [],
        permissions: this.data.permissions || {},
        admin: true, // fixed value
        role_id: null,
        selectedUserId: '',
      },
      availableUsers: [], // Will be populated from API
      adminUsers: [], // Only admin users for selection
      availableRoles: [
        "إدارة المنتجات",
        "إدارة الطلبات", 
        "إدارة العملاء",
        "إدارة المطاعم"
      ],
      roleMapping: {
        'إدارة المنتجات': 1,
        'إدارة الطلبات': 2,
        'إدارة العملاء': 3,
        'إدارة المطاعم': 4
      },
      rolePermissions: {
        "إدارة المنتجات": [],
        "إدارة الطلبات": [],
        "إدارة العملاء": [],
        "إدارة المطاعم": []
      },
      loading: false,
      assigningPermissions: false,
      loadingPermissions: false,
      removingRole: false,
      toast: useToast(),
    };
  },
      async mounted() {
      console.log('rolePopup mounted with type:', this.type, 'and data:', this.data);
      
      // Fetch users for add mode
      if (this.type === 'add') {
        await Promise.all([
          this.fetchUsers(),
          this.fetchAvailableRoles()
        ]);
      }
      
      // For edit mode, handle different scenarios
      if (this.type === 'edit') {
        if (this.data.id) {
          // Try to fetch user permissions from API
          await this.fetchUserPermissions();
        } else if (this.data.roles && this.data.roles.length > 0) {
          // If user has existing roles but no ID, map the roles directly
          console.log('User has existing roles, mapping them directly');
          this.mapExistingRoles(this.data.roles);
        } else {
          // No ID and no roles, fetch all available roles
          console.log('No user ID or roles, fetching all available roles');
          await this.fetchAllRolePermissions();
        }
      }
    },
  watch: {
    data: {
      immediate: true,
      handler(newData) {
        console.log('Data received in rolePopup:', newData);
        this.formData = {
          ...newData,
          name: newData.name || "",
          email: newData.email || "",
          phone: newData.phone || "",
          password: newData.password || "",
          role: newData.roles || newData.role || [], // Handle both roles and role properties
          permissions: newData.permissions || {},
          admin: true, // fixed value
          verify_phone: false,
          verify_email: false,
          role_id: null,
        };
        
        // If we have roles data, map them to the expected format
        if (newData.roles && newData.roles.length > 0) {
          console.log('Mapping existing roles:', newData.roles);
          this.mapExistingRoles(newData.roles);
        } else if (this.type === 'edit') {
          // If no roles exist, initialize with empty arrays
          console.log('No existing roles found, initializing empty');
          this.formData.role = [];
          this.formData.permissions = {};
        }
      },
    },
  },
  methods: {
    async fetchUsers() {
      try {
        const response = await axiosInstance.get('v1/admin/dashboard/get-all-users');
        if (response.data.status && response.data.data) {
          this.availableUsers = response.data.data;
          this.adminUsers = this.availableUsers.filter(u => u.user.role === 'admin');
        } else {
          throw new Error('Invalid response format from API');
        }
      } catch (error) {
        console.error('Error fetching users:', error);
        this.toast.error(error.response?.data?.message || error.message || 'Failed to fetch users');
      }
    },

    async fetchAvailableRoles() {
      try {
        // If you have an endpoint to fetch available roles, use it here
        // For now, we'll use the hardcoded roles
        const response = await axiosInstance.get('v1/admin/roles-permissions/roles');
        
        if (response.data.status && response.data.data) {
          // Map backend role data to our format if needed
          this.availableRoles = response.data.data.map(role => role.name || role);
          
          // Update role mapping if backend provides role IDs
          if (response.data.data.length > 0 && response.data.data[0].id) {
            this.roleMapping = {};
            response.data.data.forEach(role => {
              this.roleMapping[role.name] = role.id;
            });
          }
        }
      } catch (error) {
        console.error('Error fetching available roles:', error);
        // Fallback to hardcoded roles if API fails
        this.availableRoles = [
          "إدارة المنتجات",
          "إدارة الطلبات", 
          "إدارة العملاء",
          "إدارة المطاعم"
        ];
      }
    },

    async fetchRolePermissions(roleName) {
      this.loadingPermissions = true;
      try {
        const roleId = this.roleMapping[roleName];
        if (!roleId) {
          console.error(`Role ID not found for role: ${roleName}`);
          return;
        }

        const response = await axiosInstance.get(`v1/admin/roles-permissions/get-role-permissions/${roleId}`);
        
        if (response.data.status && response.data.data) {
          // Store both permission names and IDs
          const permissions = response.data.data.map(permission => ({
            id: permission.id,
            name: permission.name || permission
          }));
          
          // Store the full permission objects for later use
          this.rolePermissions[roleName] = permissions;
          
          // Initialize formData permissions for this role if not already set
          if (!this.formData.permissions[roleName]) {
            this.formData.permissions[roleName] = [];
          }
          
          console.log(`Fetched ${permissions.length} permissions for role: ${roleName}:`, permissions);
          console.log('Raw API response:', response.data.data);
        } else {
          console.error('Invalid response format from role permissions API');
        }
      } catch (error) {
        console.error(`Error fetching permissions for role ${roleName}:`, error);
        this.toast.error(`Failed to fetch permissions for role: ${roleName}`);
      } finally {
        this.loadingPermissions = false;
      }
    },

    onUserChange() {
      const selectedUser = this.availableUsers.find(user => user.user.id === this.formData.selectedUserId);
      if (selectedUser) {
        this.formData.name = selectedUser.user.name;
        this.formData.email = selectedUser.user.email;
      }
    },

    async fetchUserPermissions() {
      this.loading = true;
      try {
        console.log('Fetching permissions for user ID:', this.data.id);
        console.log('Full data object:', this.data);
        
        // Try different possible ID fields
        const userId = this.data.id || this.data.user_id || this.data.userId;
        console.log('Using user ID:', userId);
        
        // Check if userId exists and is valid
        if (!userId) {
          throw new Error('User ID is required but not found in data object');
        }
        
        const response = await axiosInstance.get(`v1/admin/roles-permissions/get-role-permissions-for-edit/${userId}`);
        
        if (response.data.status && response.data.data) {
          this.transformApiData(response.data.data);
        } else {
          throw new Error('Invalid response format from API');
        }
      } catch (error) {
        console.error('Error fetching user permissions:', error);
        console.error('Error response:', error.response);
        
        // If the user is not found, try a different approach
        if (error.response?.status === 404 || error.response?.data?.message?.includes('لم يتم العثور')) {
          console.log('User not found, trying to fetch all permissions for roles...');
          // Try to fetch permissions for all available roles instead
          await this.fetchAllRolePermissions();
        } else {
          this.toast.error(error.response?.data?.message || error.message || 'Failed to fetch user permissions');
        }
      } finally {
        this.loading = false;
      }
    },
    
    async fetchAllRolePermissions() {
      try {
        // Fetch permissions for all available roles
        const roles = ["إدارة المنتجات", "إدارة الطلبات", "إدارة العملاء", "إدارة المطاعم"];
        
        for (const role of roles) {
          await this.fetchRolePermissions(role);
        }
        
        // Initialize empty permissions for the user
        this.formData.permissions = {};
        roles.forEach(role => {
          this.formData.permissions[role] = [];
        });
        
        console.log('Fetched all role permissions as fallback');
      } catch (error) {
        console.error('Error fetching all role permissions:', error);
        this.toast.error('Failed to fetch role permissions');
      }
    },
    
    async fetchPermissionsForExistingRoles() {
      try {
        console.log('Fetching permissions for existing roles:', this.data.roles);
        
        // Map existing roles to Arabic names
        const roleMapping = {
          'orders': 'إدارة الطلبات',
          'restaurants': 'إدارة المطاعم',
          'customers': 'إدارة العملاء',
          'Products': 'إدارة المنتجات'
        };
        
        const transformedRoles = [];
        const transformedPermissions = {};
        
        // Process each existing role
        for (const role of this.data.roles) {
          const roleName = typeof role === 'object' ? role.name : role;
          const arabicRoleName = roleMapping[roleName] || roleName;
          
          if (arabicRoleName) {
            transformedRoles.push(arabicRoleName);
            
            // Fetch permissions for this role
            await this.fetchRolePermissions(arabicRoleName);
            
            // Initialize empty permissions for this role
            transformedPermissions[arabicRoleName] = [];
          }
        }
        
        // Update formData
        this.formData.role = transformedRoles;
        this.formData.permissions = transformedPermissions;
        
        console.log('Processed existing roles:', transformedRoles);
        console.log('Initialized permissions:', transformedPermissions);
      } catch (error) {
        console.error('Error fetching permissions for existing roles:', error);
        this.toast.error('Failed to fetch permissions for existing roles');
      }
    },
    
    mapExistingRoles(roles) {
      try {
        console.log('Mapping roles:', roles);
        
        // Map role names to Arabic equivalents
        const roleMapping = {
          'orders': 'إدارة الطلبات',
          'restaurants': 'إدارة المطاعم',
          'customers': 'إدارة العملاء',
          'Products': 'إدارة المنتجات',
          // Add reverse mapping for Arabic to English
          'إدارة الطلبات': 'إدارة الطلبات',
          'إدارة المطاعم': 'إدارة المطاعم',
          'إدارة العملاء': 'إدارة العملاء',
          'إدارة المنتجات': 'إدارة المنتجات'
        };
        
        const mappedRoles = [];
        
        for (const role of roles) {
          const roleName = typeof role === 'object' ? role.name : role;
          console.log('Processing role:', roleName);
          
          // If the role name is already in Arabic, use it directly
          if (roleName && (roleName.includes('إدارة') || roleMapping[roleName])) {
            const mappedRole = roleMapping[roleName] || roleName;
            mappedRoles.push(mappedRole);
          } else {
            // If it's a different format, try to map it or use as is
            console.log('Unknown role format:', roleName);
            mappedRoles.push(roleName);
          }
        }
        
        // Update formData with mapped roles
        this.formData.role = mappedRoles;
        
        // Initialize permissions for each role
        this.formData.permissions = {};
        mappedRoles.forEach(role => {
          this.formData.permissions[role] = [];
        });
        
        console.log('Mapped roles:', mappedRoles);
        console.log('Updated formData:', this.formData);
        
        // Fetch permissions for these roles
        this.fetchPermissionsForMappedRoles(mappedRoles);
      } catch (error) {
        console.error('Error mapping existing roles:', error);
        // Fallback: use roles as they are
        this.formData.role = roles.map(role => typeof role === 'object' ? role.name : role);
        this.formData.permissions = {};
        this.formData.role.forEach(role => {
          this.formData.permissions[role] = [];
        });
      }
    },
    
    async fetchPermissionsForMappedRoles(roles) {
      try {
        for (const role of roles) {
          await this.fetchRolePermissions(role);
        }
      } catch (error) {
        console.error('Error fetching permissions for mapped roles:', error);
      }
    },
    
    transformApiData(apiData) {
      // Transform API data to match our component structure
      const transformedRoles = [];
      const transformedPermissions = {};
      
      apiData.forEach(module => {
        // Map module names to Arabic role names
        const roleMapping = {
          'orders': 'إدارة الطلبات',
          'restaurants': 'إدارة المطاعم',
          'customers': 'إدارة العملاء',
          'Products': 'إدارة المنتجات'
        };
        
        const roleName = roleMapping[module.module];
        if (roleName) {
          transformedRoles.push(roleName);
          
          // Store the full permission objects for this role
          this.rolePermissions[roleName] = module.permissions.map(permission => ({
            id: permission.id,
            name: permission.name
          }));
          
          // Transform permissions for this role - store permission IDs of permissions that user has
          const permissions = module.permissions
            .filter(permission => permission.has_permission)
            .map(permission => permission.id);
          
          transformedPermissions[roleName] = permissions;
        }
      });
      
      // Update formData with the fetched permissions
      this.formData.role = transformedRoles;
      this.formData.permissions = transformedPermissions;
      
      console.log('Transformed roles:', transformedRoles);
      console.log('Transformed permissions:', transformedPermissions);
      console.log('Role permissions structure:', this.rolePermissions);
    },
    

    
    async addRole(event) {
      const selectedRole = event.target.value;
      if (selectedRole && !this.formData.role.some(role => {
        const roleName = typeof role === 'object' ? role.name : role;
        return roleName === selectedRole;
      })) {
        this.formData.role.push(selectedRole);
        // Set role_id for the selected role
        this.formData.role_id = this.roleMapping[selectedRole] || null;
        // Initialize permissions array for the new role
        if (!this.formData.permissions[selectedRole]) {
          this.formData.permissions[selectedRole] = [];
        }
        if (this.type === 'add') {
          await this.fetchRolePermissions(selectedRole);
        }
      }
      event.target.value = ""; // Reset select
    },
    async removeRole(roleToRemove) {
      this.removingRole = true;
      try {
        const roleName = typeof roleToRemove === 'object' ? roleToRemove.name : roleToRemove;
        const roleId = this.roleMapping[roleName];
        
        // If we're in edit mode and have a user ID, remove the role from the user via API
        if (this.type === 'edit' && this.data.id && roleId) {
          const response = await axiosInstance.post('v1/admin/roles-permissions/remove-role-from-user', {
            user_id: this.data.id,
            role_id: roleId
          });

          if (!response.data.status) {
            throw new Error(response.data.message || 'Failed to remove role from user');
          }

          this.toast.success("Role removed successfully");
        }

        // Remove role from local form data
        this.formData.role = this.formData.role.filter(role => {
          const currentRoleName = typeof role === 'object' ? role.name : role;
          return currentRoleName !== roleName;
        });
        
        // Remove permissions for the removed role
        if (this.formData.permissions[roleName]) {
          delete this.formData.permissions[roleName];
        }
      } catch (error) {
        console.error('Error removing role:', error);
        this.toast.error(error.response?.data?.message || error.message || 'Failed to remove role');
      } finally {
        this.removingRole = false;
      }
    },
    getSelectedPermissionsForRole(role) {
      const roleName = typeof role === 'object' ? role.name : role;
      const selectedPermissionIds = this.formData.permissions[roleName] || [];
      
      // Convert permission IDs back to names for display
      const rolePermissions = this.rolePermissions[roleName] || [];
      return selectedPermissionIds.map(permissionId => {
        const permission = rolePermissions.find(p => p.id === permissionId);
        return permission ? permission.name : permissionId;
      });
    },
    validateForm() {
      if (this.type === 'add') {
        // Only validate admin user selection
        if (!this.formData.selectedUserId) {
          this.toast.error(this.$t("SelectAdminUser") + " " + this.$t("isRequired"));
          return false;
        }
        // Role validation
        if (this.formData.role.length === 0) {
          this.toast.error(this.$t("Role") + " " + this.$t("isRequired"));
          return false;
        }
      } else {
        // Edit mode validations
        if (!this.formData.name || this.formData.name.trim() === "") {
          this.toast.error(this.$t("Name") + " " + this.$t("isRequired"));
          return false;
        }
        const emailStr = this.formData.email ? this.formData.email.toString().trim() : "";
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailStr) {
          this.toast.error(this.$t("email") + " " + this.$t("isRequired"));
          return false;
        }
        if (!emailRegex.test(emailStr)) {
          this.toast.error(this.$t("email") + " " + this.$t("isInvalid"));
          return false;
        }
      }
      return true;
    },
    async saveRole() {
      if (this.validateForm()) {
        this.assigningPermissions = true;
        try {
          if (this.type === 'add') {
            // For add mode, create a new user with all fields
            await this.createNewUser();
          } else if (this.type === 'edit') {
            await this.assignPermissionsToExistingRoles();
            this.$emit("save", this.formData);
            this.toast.success(this.$t("RoleSavedSuccessfully"));
          }
        } catch (error) {
          console.error('Error saving role:', error);
          this.toast.error(error.response?.data?.message || error.message || 'Failed to save role');
        } finally {
          this.assigningPermissions = false;
        }
      }
    },
    async createNewUser() {
      try {
        // Prepare payload for new user
        const payload = {
          user_id: this.formData.selectedUserId,
          role_id: this.formData.role_id,
          role: 'admin',
          permissions: this.formData.permissions,
        };
        const response = await axiosInstance.post('https://backend.alaqdk.com/api/v1/admin/users/store/new', payload);
        if (!response.data.status) {
          throw new Error(response.data.message || 'Failed to create user');
        }
        this.toast.success(this.$t("UserCreatedSuccessfully"));
        this.$emit("save", this.formData);
      } catch (error) {
        console.error('Error creating user:', error);
        throw error;
      }
    },



    async assignPermissionsToExistingRoles() {
      try {
        // Assign permissions to each role
        for (const role of this.formData.role) {
          const roleId = this.roleMapping[role];
          if (roleId) {
            const selectedPermissions = this.formData.permissions[role] || [];
            console.log(`Selected permissions for role ${role}:`, selectedPermissions);
            
            // Always call the API, even with empty permissions (to clear existing permissions)
            await this.assignPermissionsToRole(roleId, selectedPermissions);
          }
        }
      } catch (error) {
        console.error('Error assigning permissions to existing roles:', error);
        throw error;
      }
    },

    async assignRolesToUser() {
      try {
        // Use the selected user ID from add mode or the current user ID from edit mode
        const userId = this.type === 'add' ? this.formData.selectedUserId : this.data.id;
        
        if (!userId) {
          throw new Error('User ID is required');
        }
        
        // Assign each selected role to the user
        for (const role of this.formData.role) {
          const roleId = this.roleMapping[role];
          if (roleId) {
            // First assign the role to the user
            const roleResponse = await axiosInstance.post('v1/admin/roles-permissions/assign-role-to-user', {
              user_id: userId,
              role_id: roleId
            });

            if (!roleResponse.data.status) {
              throw new Error(roleResponse.data.message || 'Failed to assign role');
            }

            // Then assign permissions to the role if any are selected
            const selectedPermissions = this.formData.permissions[role] || [];
            console.log(`Selected permissions for role ${role}:`, selectedPermissions);
            
            // Always call the API, even with empty permissions (to clear existing permissions)
            await this.assignPermissionsToRole(roleId, selectedPermissions);
          }
        }

        this.toast.success(this.$t("RoleSavedSuccessfully") + " - " + this.$t("PermissionsAssignedSuccessfully"));
        this.$emit("save", this.formData);
      } catch (error) {
        console.error('Error assigning roles to user:', error);
        throw error;
      }
    },

    async assignPermissionsToRole(roleId, permissions) {
      try {
        // Send permissions as an array of IDs
        const requestBody = {
          role_id: roleId,
          permissions: permissions // This should now be an array of permission IDs
        };

        console.log('Sending permissions request:', requestBody);

        const response = await axiosInstance.post('v1/admin/roles-permissions/assign-permissions-to-role', requestBody);

        if (!response.data.status) {
          throw new Error(response.data.message || 'Failed to assign permissions to role');
        }

        console.log(`Successfully assigned ${permissions.length} permissions to role ${roleId}`);
      } catch (error) {
        console.error('Error assigning permissions to role:', error);
        
        // Log the detailed error response
        if (error.response) {
          console.error('Error response data:', error.response.data);
          console.error('Error response status:', error.response.status);
          console.error('Error response headers:', error.response.headers);
        }
        
        // If it's a validation error, show the specific validation messages
        if (error.response && error.response.data && error.response.data.errors) {
          const errorMessages = Object.values(error.response.data.errors).flat().join(', ');
          throw new Error(`Validation error: ${errorMessages}`);
        }
        
        throw new Error(`Failed to assign permissions to role ${roleId}: ${error.message}`);
      }
    },

    deleteRole() {
      this.$emit("delete", this.formData.code);
      this.toast.success(this.$t("RoleDeletedSuccessfully"));
    },
  },
};
</script>

